; Cartridge header: start vectors and CBM80 signature
; $8000-$8008

; Cartridge header. At a hardware reset, the KERNAL finds the signature at $8004 and jumps through the cold start vector.
cart_cold_start_vector
cart_warm_start_vector = * + 2
cartridge_signature = * + 4
!zone patch_CRACK_HOTLINE_8000 {
.patch_start
!if CRACK_HOTLINE {
        ; CRACK_HOTLINE on: 9 bytes at $8000-$8008, NOP after the code
        ; Hotline removed the CBM80 cartridge header, so RESET does not restart the game. Only RESET changes: the game sets the NMI vector to an RTI, so RESTORE did nothing before either.
!fill 9, $00
        !if ((* - .patch_start) & $ffff) > 9 { !error "The patch CRACK_HOTLINE at $8000 has ", ((* - .patch_start) & $ffff), " bytes; the range has 9." } else { !fill 9 - ((* - .patch_start) & $ffff), $ea }
} else {
        !word start                     ; Cold start address: $8009.
        !word start                     ; Warm start address: $8009. RESTORE does not use it: the game sets the NMI vector to an RTI.
        !pet "CBM80"                    ; The signature CBM80 (C, B, M with bit 7 set, then 8 and 0).
}
}
